<script setup>
import { computed } from 'vue';

const props = defineProps({
    variant: {
        type: String,
        default: 'mark',
        validator: (v) => ['mark', 'horizontal', 'stacked', 'slogan'].includes(v),
    },
    tone: {
        type: String,
        default: 'color',
        validator: (t) => ['color', 'mono', 'mono-ink', 'white', 'mono-white', 'reversed'].includes(t),
    },
    asImg: {
        type: Boolean,
        default: false,
    },
    alt: {
        type: String,
        default: 'Teri (ጠሪ)',
    },
});

const normalizedTone = computed(() => {
    if (props.tone === 'white') return 'mono-white';
    if (props.tone === 'mono') return 'mono-ink';
    return props.tone;
});

const filename = computed(() => {
    let name = `teri-`;
    if (props.variant === 'mark') name += 'mark';
    else if (props.variant === 'horizontal') name += 'lockup-horizontal';
    else if (props.variant === 'stacked') name += 'lockup-stacked';
    else if (props.variant === 'slogan') name += 'lockup-with-slogan';

    if (normalizedTone.value === 'reversed') name += '-reversed';
    else if (normalizedTone.value === 'mono-ink') name += '-mono-ink';
    else if (normalizedTone.value === 'mono-white') name += '-mono-white';

    return `${name}.svg`;
});

const src = computed(() => `/brand/${filename.value}`);

// Outlined path constants
const PATH_MARK = "M 18.0 52.5 L 18.0 75.8 Q 18.0 78.0 20.2 78.0 L 26.2 78.0 Q 28.4 78.0 28.4 75.8 L 28.4 52.8 Q 28.4 46.5 31.8 40.5 Q 36.8 36.0 43.2 36.0 Q 44.0 36.0 44.8 36.1 L 44.8 75.8 Q 44.8 78.0 47.0 78.0 L 53.0 78.0 Q 55.2 78.0 55.2 75.8 L 55.2 38.5 Q 57.5 36.8 61.5 36.0 Q 64.5 36.0 68.0 37.5 Q 71.6 40.5 71.6 48.0 L 71.6 75.8 Q 71.6 78.0 73.8 78.0 L 79.8 78.0 Q 82.0 78.0 82.0 75.8 L 82.0 45.6 Q 82.0 39.5 78.8 33.5 Q 74.0 27.9 66.0 27.9 Q 61.5 27.9 57.0 29.8 Q 55.2 30.8 55.2 31.2 L 55.2 27.9 L 43.0 27.9 Q 34.5 27.9 25.2 32.5 Q 18.0 41.5 18.0 52.5 Z";

const colors = computed(() => {
    const t = normalizedTone.value;
    if (t === 'mono-white') {
        return {
            tileBg: '#FFFFFF',
            dot: '#1C2140',
            glyph: '#1C2140',
            text: '#FFFFFF',
            slogan: '#F4B400',
            subtext: '#E4E3EE',
        };
    }
    if (t === 'mono-ink') {
        return {
            tileBg: '#1C2140',
            dot: '#FFFFFF',
            glyph: '#FFFFFF',
            text: '#1C2140',
            slogan: '#1C2140',
            subtext: '#1C2140',
        };
    }
    if (t === 'reversed') {
        return {
            tileBg: '#1C2140',
            dot: '#F4B400',
            glyph: '#F6F5FA',
            text: '#F6F5FA',
            slogan: '#F4B400',
            subtext: '#E4E3EE',
        };
    }
    // Default 'color'
    return {
        tileBg: '#1C2140',
        dot: '#F4B400',
        glyph: '#F6F5FA',
        text: '#1C2140',
        slogan: '#F4B400',
        subtext: '#6B7280',
    };
});
